(window.DETAIL_C = window.DETAIL_C || {})["phy-12-16"] = {"phy-12-16-m01":{"idea":"A p-n diode conducts well only in forward bias.","steps":["Forward bias: the p side goes to the positive terminal.","The applied voltage opposes the barrier and narrows the depletion layer.","So the current rises quickly."],"others":"In reverse bias the barrier is higher and only a tiny leakage current flows. Joining the p side to the negative terminal is also reverse bias.","trap":"Forward: p to +, n to −.","answer":"forward biased, with the p side joined to the positive terminal"},"phy-12-16-m02":{"idea":"A rectifier turns AC into DC.","steps":["It uses the one-way conduction of a diode.","The output is pulsating DC.","A filter then smooths it."],"others":"Raising the voltage is a transformer. DC to AC is an inverter. Storing charge is a capacitor.","trap":"Rectifier: AC to DC.","answer":"changes alternating current into direct current"},"phy-12-16-m03":{"idea":"A half wave rectifier gives one pulse per cycle and a full wave rectifier gives two.","steps":["Half wave: one pulse per input cycle, so the output frequency is 50 Hz.","Full wave: both half cycles give pulses in the same direction, so two pulses per cycle.","The output frequency is 100 Hz."],"others":"Equal frequencies, or the reverse order, do not match the number of pulses per cycle.","trap":"Full wave doubles the ripple frequency.","answer":"50 Hz and 100 Hz"},"phy-12-16-m04":{"idea":"A full wave rectifier uses both halves of the AC cycle.","steps":["A half wave rectifier wastes one half of every cycle.","A full wave rectifier uses both halves.","So the output is larger and the ripple is less."],"others":"A smaller output would be worse, not better. A full wave rectifier does not avoid the transformer. Using one half cycle describes the half wave rectifier.","trap":"Efficiency: full wave 81.2%, half wave 40.6%.","answer":"uses both half cycles, so the output is larger and the ripple is less"},"phy-12-16-m05":{"idea":"The ripple factor says how much AC is left in the DC output.","steps":["It is the ratio of the rms value of the AC part to the DC value.","A smaller ripple factor means smoother DC.","That is the better rectifier."],"others":"Peak to rms of the input, output power to input power (efficiency), and DC to AC are different ratios.","trap":"Small ripple is good.","answer":"the rms value of the AC component to the DC value of the output"},"phy-12-16-m06":{"idea":"A capacitor across the load smooths the output.","steps":["It charges up to the peak of each pulse.","It discharges through the load between pulses.","This fills the gaps and reduces the ripple."],"others":"Increasing the ripple is the opposite. Blocking the DC would remove the output. It cannot raise the DC above the peak.","trap":"Capacitor in parallel with the load.","answer":"reduce the ripple, by charging at the peaks and discharging in between"},"phy-12-16-m07":{"idea":"A Zener diode regulates voltage in its reverse breakdown region.","steps":["In breakdown, a large change in current changes the voltage very little.","The voltage across the diode stays close to the Zener voltage.","The load connected in parallel gets that steady voltage."],"others":"A forward bias region does not regulate in this way. In breakdown, the voltage stays nearly constant, not the current.","trap":"Zener: reverse bias, breakdown, constant voltage.","answer":"reverse breakdown region, where the voltage stays almost constant"},"phy-12-16-m08":{"idea":"A photodiode works in reverse bias and its current follows the light.","steps":["In reverse bias there is only a small dark current.","Light makes new electron-hole pairs in the depletion region.","The current rises in proportion to the light intensity."],"others":"Forward bias would swamp the small light-made current. No bias is the solar cell mode. The current does not fall with more light.","trap":"Photodiode: reverse bias. LED: forward bias.","answer":"reverse bias, where the current rises with the intensity of the light"},"phy-12-16-m09":{"idea":"An LED gives out light when electrons and holes recombine in forward bias.","steps":["Forward bias pushes electrons and holes towards the junction.","They recombine there and release energy.","The energy comes out as photons. The colour depends on the energy gap."],"others":"Reverse bias does not bring carriers to the junction. Separation of carriers does not give out light.","trap":"LED: forward bias, recombination.","answer":"forward biased, as the electrons and holes recombine at the junction"},"phy-12-16-m10":{"idea":"A solar cell makes its own voltage, with no external bias.","steps":["Light makes electron-hole pairs near the junction.","The built-in field separates them.","That gives a voltage between the two sides, so the cell can drive a current."],"others":"A solar cell does not take in voltage from outside, and it is not limited to reverse or forward bias.","trap":"Photodiode needs bias. Solar cell does not.","answer":"works with no external bias, and it generates its own voltage"},"phy-12-16-m11":{"idea":"The base of a transistor is thin and lightly doped.","steps":["A thin base gives carriers little chance to recombine.","Light doping also means few recombinations.","So most carriers reach the collector."],"others":"A thick base would lose too many carriers. Heavy doping in the base would also cause recombination.","trap":"Base: thin and lightly doped. Emitter: heavily doped.","answer":"very thin and lightly doped"},"phy-12-16-m12":{"idea":"For amplification, the emitter junction is forward biased and the collector junction is reverse biased.","steps":["The forward biased emitter-base junction injects carriers.","The reverse biased collector-base junction collects them.","This is the active region."],"others":"Reverse on both is cutoff. Forward on both is saturation. Reverse on the emitter side and forward on the collector side is the inverted mode.","trap":"Active region: EB forward, CB reverse.","answer":"forward bias on the emitter-base junction, with reverse bias on the collector-base junction"},"phy-12-16-m13":{"idea":"The emitter current splits into the base and collector currents.","steps":["By Kirchhoff's law, I_E = I_B + I_C.","The base is thin, so only a few percent of carriers leave through it.","So I_B is much smaller than I_C."],"others":"I_B larger than I_C is wrong. The forms with I_B − I_C and I_C = I_B + I_E break Kirchhoff's law.","trap":"I_C is a little less than I_E.","answer":"I_E = I_B + I_C, and I_B is much smaller than I_C"},"phy-12-16-m14":{"idea":"The current gains α and β are linked through I_E = I_B + I_C.","steps":["I_E = I_B + I_C gives 1/α = 1 + 1/β.","So β = α/(1 − α).","I_C is a little less than I_E, so α is a little less than 1 (for example 0.98)."],"others":"(1 − α)/α is upside down. α slightly more than 1 is impossible. α/(1 + α) has the wrong sign.","trap":"α is below 1, β is large.","answer":"β = α/(1 − α), and α is slightly less than 1"},"phy-12-16-m15":{"idea":"A common emitter amplifier inverts the signal.","steps":["A rise in the input raises the base current and the collector current.","The voltage drop across the load rises.","So the collector voltage falls: the output is 180° out of phase."],"others":"270° and 90° are not the phase shifts of this amplifier. In phase would be a common base or common collector stage.","trap":"The minus sign in the gain formula means 180°.","answer":"out of phase with the input voltage by 180°"},"phy-12-16-m16":{"idea":"A transistor does not make energy. The DC supply provides the extra power.","steps":["The transistor controls how much of the DC supply goes to the load.","It follows the small input signal.","So the extra output power comes from the DC source."],"others":"Heat of the transistor, the input signal, or creation of energy are not the source of power.","trap":"Power gain does not break energy conservation.","answer":"is supplied by the DC power source, not by the transistor"},"phy-12-16-m17":{"idea":"AND gives 1 only if every input is 1.","steps":["AND is logical multiplication: Y = A·B.","The output is 1 only for A = 1 and B = 1.","Any 0 in the inputs gives 0."],"others":"Any one input being 1 is the OR gate. All inputs 0 gives 0. Unequal inputs describe XOR.","trap":"AND = all.","answer":"all its inputs are 1"},"phy-12-16-m18":{"idea":"OR gives 0 only when all the inputs are 0.","steps":["OR is logical addition: Y = A + B.","The output is 1 if A or B (or both) is 1.","It is 0 only for A = B = 0."],"others":"Both inputs 1 gives 1. At least one input 0 does not force 0. Different inputs give 1.","trap":"OR = at least one.","answer":"only when both the inputs are 0"},"phy-12-16-m19":{"idea":"A NOT gate flips its input.","steps":["NOT is inversion: Y = A′.","With input 1, the output is 0.","With input 0, the output is 1."],"others":"2 is not a logic value. 1 would mean no inversion. The output is always defined.","trap":"NOT swaps 0 and 1.","answer":"0"},"phy-12-16-m20":{"idea":"NAND and NOR are universal gates.","steps":["Any other gate can be built from NAND alone, or from NOR alone.","For example, a NAND with its inputs joined is a NOT.","A NAND followed by a NOT is an AND."],"others":"NOT alone cannot build the others. AND, OR and XOR cannot make every gate by themselves.","trap":"Universal gates: NAND and NOR.","answer":"NAND and NOR are universal gates, as any other gate can be made from them"},"phy-12-16-m21":{"idea":"NOR is OR followed by NOT.","steps":["A = 1 and B = 0, so A + B = 1.","NOT of 1 is 0.","So the NOR output is 0."],"others":"The other options use AND, or skip the inversion, which does not describe NOR.","trap":"NOR gives 1 only when both inputs are 0.","answer":"0, since the OR of the inputs is 1 and it is then inverted"},"phy-12-16-m22":{"idea":"XOR means exclusive OR.","steps":["The output is 1 when exactly one input is 1.","That means the two inputs are different.","For (0, 0) and (1, 1) the output is 0."],"others":"Both inputs 0 or both 1 give 0. 'The same' is the XNOR condition.","trap":"XOR = different.","answer":"when the two inputs are different from each other"},"phy-12-16-m23":{"idea":"Joining the inputs of a NAND gate makes a NOT gate.","steps":["NAND = NOT(A·B).","With both inputs A: NOT(A·A).","A·A = A, so the output is A′, which is a NOT gate."],"others":"A + A would be an OR of two equal inputs. A alone would be a buffer. A constant 1 does not follow.","trap":"A NAND with joined inputs inverts.","answer":"A′, so it works as a NOT gate"},"phy-12-16-n01":{"idea":"The common-emitter current gain is β = I_C/I_B.","steps":["I_C = 2.0 mA = 2.0 × 10⁻³ A and I_B = 40 μA = 40 × 10⁻⁶ A.","β = 2.0 × 10⁻³/(40 × 10⁻⁶) = 50, a pure number."],"trap":"Convert both currents to the same unit.","answer":"50"},"phy-12-16-n02":{"idea":"Emitter current is the sum of the base and collector currents.","steps":["I_C = β I_B = 99 × 25 μA = 2.475 mA.","I_E = I_B + I_C = 0.025 + 2.475.","I_E = 2.50 mA."],"trap":"Check: I_E = (1 + β) I_B = 100 × 25 μA = 2.5 mA.","answer":"2.50 mA"},"phy-12-16-n03":{"idea":"The voltage gain is β_AC R_L/r_i.","steps":["β_AC = 60, R_L = 3000 Ω and r_i = 1000 Ω.","|A_v| = 60 × 3000/1000.","|A_v| = 180."],"trap":"The minus sign shows phase inversion; the question asks for the size only.","answer":"180"},"phy-12-16-n04":{"idea":"Power gain is current gain times voltage gain.","steps":["A_p = β_AC × A_v.","= 60 × 180.","= 10 800."],"trap":"Check: (60)² × 3000/1000 = 10 800.","answer":"10800"},"phy-12-16-n05":{"idea":"A half wave rectifier has a DC output of V_m/π.","steps":["Peak voltage V_m = √2 × 20 = 28.28 V.","V_dc = V_m/π = 28.28/3.1416.","V_dc = 9.00 V."],"trap":"Convert rms to peak first.","answer":"9.00 V"},"phy-12-16-n06":{"idea":"A full wave rectifier has a DC output of 2V_m/π.","steps":["V_m = √2 × 20 = 28.28 V.","V_dc = 2V_m/π = 56.57/3.1416.","V_dc = 18.01 V."],"trap":"Twice the half-wave value.","answer":"18.01 V"},"phy-12-16-n07":{"idea":"The ripple factor compares the rms and DC values of the output.","steps":["Half wave: V_rms = V_m/2 and V_dc = V_m/π.","r = √((V_rms/V_dc)² − 1) = √(π²/4 − 1).","r = √(1.467) = 1.21."],"trap":"A ripple above 1 means more AC than DC.","answer":"1.21"},"phy-12-16-n08":{"idea":"Full wave rectification gives a much lower ripple factor.","steps":["Full wave: V_rms = V_m/√2 and V_dc = 2V_m/π.","r = √((π/(2√2))² − 1) = √(π²/8 − 1).","r = √(0.2337) = 0.48."],"trap":"0.48 is smaller than 1.21 for half wave.","answer":"0.48"},"phy-12-16-n09":{"idea":"The Zener current is the series current minus the load current.","steps":["Current in the series resistor = (12 − 6)/300 = 20 mA.","Current in the load = 6/1000 = 6 mA.","Zener current = 20 − 6 = 14 mA.","Power = 6 V × 14 mA = 84 mW."],"trap":"The load and the Zener are in parallel.","answer":"84 mW"},"phy-12-16-n10":{"idea":"Convert α to β with β = α/(1 − α).","steps":["α = 0.98.","1 − α = 0.02.","β = 0.98/0.02 = 49."],"trap":"Check with I_E = 1 mA: I_C = 0.98 mA and I_B = 0.02 mA.","answer":"49"},"phy-12-16-n11":{"idea":"Y = 1 only when the inside of the NOT is 0.","steps":["Y is the NOT of A·B + C, so Y is 1 only when A·B + C = 0.","That needs C = 0, which leaves 4 of the 8 combinations.","Among those, A·B must also be 0, which excludes A = B = 1.","The valid inputs are (0,0,0), (0,1,0) and (1,0,0), so there are 3."],"trap":"Both A·B and C must be 0.","answer":"3"}};
